    "この照明デザインに名前を付けて保存（ファイルにも書き出せます）": "為此燈光設計命名並儲存（也可匯出檔案）",
    "変更した配置と照明デザインを現在のショーのLXキューへ適用": "將編輯後的配置和燈光設計套用到目前演出的 LX 提示",
    "このブラウザでの直近の4図描画時間です。CPU・メモリの使用量そのものではありません。": "此瀏覽器最近繪製四個視圖的耗時，並非 CPU 或記憶體使用量。",
    "この明かりをシーンへ保存します。適用すると詳細表示へ移り、細かく編集できます": "將此燈光儲存到場景。套用後進入詳細編輯。",
    "劇場サイズに合う仮想仕込みを入れ、右の「見本」タブから照明のあるあるを当てていきます": "設定適合劇場尺寸的虛擬配置，再從右側範例分頁選擇燈光範例。",
    "灯体の点灯を切り替える": "切換燈具開關",
    "編集中の照明を名前付きで残す・ファイルへ書き出す": "為編輯中的燈光命名並儲存或匯出檔案",
    "1灯だけなので位置は変えません": "僅選擇一個燈具，位置保持不變",
    "例: 中央ムービング": "例如：中央搖頭燈",
    "混色＝CMY/RGB で途中の色を作れる（フェードで混ざる）。カラーホイール＝色板を回す機種。途中の色が無いので、スナップの遅れの後に一瞬で替わる": "混色：CMY/RGB 在漸變中混合中間色。色輪：旋轉色片，在切換延遲後瞬間換色。",
    "灯体の設置位置名": "燈具安裝位置名稱",
    "灯体を配置する設置区間": "燈具的安裝區間",
    "距離を0.1m減らす": "距離減少 0.1 m",
    "距離を0.1m増やす": "距離增加 0.1 m",
