    "起点からの距離（m）": "距起點的距離（m）",
    "GALの回廊と設置レール、客席側面フロントの平面図": "GAL 迴廊、安裝軌道及觀眾席側面面光的平面圖",
    "色を作る（作った色はショー全体で使えます）": "建立顏色（整個演出均可使用）",
    "押すと光を四角に切ります（幅と奥行きを決められます）": "按下將光束切為矩形（可調整寬度和深度）",
    "光を四角に切っています。押すと丸に戻します（形は覚えておきます）": "矩形切光已啟用。按下恢復圓形光束（保留形狀）",
    "光の輪に内接する正方形を100とした%": "以光束內接正方形為 100 的百分比",
    "押すと動きの終点に別の色を置き、位置と同じ位相で色が移ります": "按下設定終點顏色，與位置同步變化",
    "押すと始点と終点を置いて位置を動かします": "按下設定起點和終點以移動位置",
    "押すと光量に始点と終点を置いて動かします": "按下設定起始和結束光量以進行變化",
    "押すと広がりに始点と終点を置いて動かします": "按下設定起始和結束光束範圍以進行變化",
