  "旧 Lite の保存を確認できませんでした。再読み込みしてお試しください。": "無法檢查舊 Lite 儲存。請重新整理後重試。",

    "演者の体型と肩・首・手足のつながりを、なめらかな形に整えました。": "調整了演員的體型，使肩部、頸部和四肢的連接更加平滑。",
    "シーン転換の移動に、足を着いて歩く動きを追加しました。停止中は設定した姿勢を保ちます。": "場景切換時加入了雙腳著地的行走動作。靜止時保持所選姿勢。",
