    "劇場設定の未適用の編集は破棄されます。作りかけのショーは一覧に残します。前のショーへ戻りますか？": "劇場設定中尚未套用的編輯將被捨棄。未完成的演出會保留在列表中。要返回上一個演出嗎？",
    "劇場設定の未適用の編集は破棄されます。いまのショーは一覧に残します。別のショーを開きますか？": "劇場設定中尚未套用的編輯將被捨棄。目前的演出會保留在列表中。要開啟其他演出嗎？",
    "劇場の寸法が変わると、現在の照明が動かなくなる可能性があります。変更後に各シーンの照明を点検してください。寸法を変更しますか？": "劇場尺寸改變後，目前的照明可能無法正常運作。變更後請檢查每個場景的照明。要變更尺寸嗎？",
