    "装置（「大道具を追加」の「効果の装置」）を置くと、雨と雪はその幅の下に、シャボン玉は装置から出ます。火柱は噴出口の上にだけ立ちます。「シーンを動かす」が入っていると動きます。": "放置裝置（新增大道具→效果裝置）後，雨和雪只在其寬度下方落下，肥皂泡從裝置冒出。火柱只在噴口上方出現。開啟「場景動畫」時會動。",
