    "光だまりに入っている演者を、その明かりの色を掛けた色で描く。赤い明かりの下で青い衣装が沈むシーンに気づけます（「明かりの見え方」が切のときは効きません）": "把站在光斑中的演員依燈光顏色相乘後的顏色繪製，能發現藍色服裝在紅光下發黑的場景（「燈光的顯示方式」為關時無效）",
    "明かりの見え方": "燈光的顯示方式",
    "切（いまの概略）": "關閉（僅示意）",
    "光だまり": "光斑",
    "＋光の筋": "＋光束",
    "本番の暗さ": "演出時的暗度",
    "シーンのキューで点いている灯体の見え方。下の段ほど図が重くなります。「本番の暗さ」は作業灯を消して、光の当たる所だけを見せます": "本場景燈光提示中點亮燈具的顯示方式。越往下越吃效能。「演出時的暗度」會關掉工作燈，只顯示被燈光照到的地方",
    "客席の床を0とした高さです。−3〜3mまで、0.05mきざみ。マイナスは客席より低い舞台（サーカスのピステなど）。空欄のままなら、いままでどおりの見え方になります。": "以觀眾席地面為0的高度。可填−3〜3m，以0.05m為一檔。負值表示舞台低於觀眾席（如馬戲團的圓形演區）。留空則維持現在的樣子。",
    "3. 追加のステージを選択してください": "3. 選擇追加舞台形狀",
    "4. 天井を設定してください": "4. 設定天花板",
  "前一文字幕の有無": "有無前簷幕",
  "この劇場には前一文字幕がありません": "此劇場沒有前簷幕。",
  "前一文字幕ありにしました。": "已設置前簷幕。",
  "前一文字幕なしにしました。正面図・3D・プレビューに描きません。": "已取消前簷幕。正面圖、3D和預覽均不顯示。",
  "壁は幅・奥行とも0.05m以上で、会場の外枠の内側に描いてください。": "牆的寬度和深度至少為0.05m，請畫在劇場輪廓內。",
    "天井あり": "有天花板",
    "天井なし": "無天花板",
    "天井の有無": "有無天花板",
    "前一文字の有無": "有無前簷幕",
    "幕あり": "有前簷幕",
    "幕なし": "無前簷幕",
    "開口高さ": "開口高度",
    "舞台床から幕の下端まで。天井高より低く設定します。": "從舞台地面到幕布下緣的高度，須低於天花板高度。",
    "前一文字は天井のある劇場式ステージで設定できます。幕は舞台前端に置きます。": "有天花板的劇場式舞台可設定前簷幕，幕布位於舞台前緣。",
    "天井なしでは高さと吊りを使いません。入力した値は残します。": "無天花板時不使用高度與吊掛。已輸入的數值會保留。",
    "天井なしでは高さ・吊り・前一文字を使いません。入力した値は残します。": "無天花板時不使用高度、吊掛與前簷幕。已輸入的數值會保留。",
    "5. 客席を配置してください": "5. 配置觀眾區",
    "6. 舞台袖を配置してください": "6. 配置側台區域",
    "7. 壁を設置してください": "7. 設置牆體",
    "8. 舞台機構を設定してください": "8. 設定舞台機構",
    "四角または丸を選び、右の平面図でドラッグしてください。高さは天井と同じです。通れない場所として扱います。": "選擇方形或圓形，在右側平面圖上拖曳。高度與天花板相同，視為無法通行的位置。",
    "四角または丸を選び、右の平面図でドラッグしてください。": "請選擇矩形或圓形，然後在右側平面圖中拖曳。",
    "既存の舞台につながる位置へ追加できます。": "可新增在與現有舞台相連的位置。",
    "追加した四角・丸はドラッグで動かせます。重なる部分は合成できます。": "可拖曳已新增的矩形和圓形。重疊部分可以合併。",
    "キャンセルすると、重なりのもとになった直前の操作を取り消します。": "取消會復原造成重疊的上一步操作。",
    "ドラッグで回せます": "拖曳可旋轉",
    "自動で回ります。ドラッグでも回せます": "會自動旋轉，也可以拖曳",
    "この道具の見え方。ドラッグで回せます": "這個道具的樣子。拖曳可旋轉",
    "バージョンを切り替える": "切換版本",
    "ほかの版はまだありません。": "還沒有其他版本。",
    "選ぶとその版を開きます。いま開いている版には印が付いています。": "選擇後會開啟該版本。目前開啟的版本帶有標記。",
    "開いています": "正在開啟",
    "もとの版はそのまま残ります。": "原本的版本維持不變。",
    "メモ（省略可）": "備註（可留空）",
    "プリセットを適用する": "套用預設",
    "プリセットを適用しますか？": "要套用預設嗎？",
    "手順1〜7で変えた内容は失われます。取り消し（⌘Z）で戻せます。": "在步驟1〜7中所做的變更會遺失。可用復原（⌘Z）還原。",
    "重なりを合成": "合併重疊部分",
    "既存の舞台につながる位置へ追加できます。合成後は一体の舞台面になり、戻すで解除できます。": "可新增在與現有舞台相連的位置。合併後將成為一個舞台面，可透過復原還原。",
    "離れた位置にも、何個でも追加できます。重なる形は合成すると一体の舞台面になり、戻すで解除できます。": "可在分開的位置新增任意數量的舞台。重疊的形狀合併後將成為一個舞台面，可透過復原還原。",
    /* ★2026-10-06（v0.3.13 下ごしらえ・D6）: 劇場設定の画面で訳が無かった文。韓・中は下訳 */
    "0. 照明": "0. 燈光",
    "0.1〜100mの範囲で入力できます。": "可輸入 0.1~100 m 範圍內的值。",
