      "theatre-tram": "世田谷公共劇場位於三軒茶屋的實驗劇場。下沉式盡端舞台：沒有鏡框，舞台與觀眾席同處一個盒子。平面呈T形——8.4米的上舞台盒體收窄後，展開為14.7米的主空間。一座升降台（5.44×2.72米）位於台口附近的中央；基本形態225席。",
