  "同梱の見本ショーは、一覧だけを先に読み込み、開くときに本文を読み込むようにして、起動を軽くしました。保存したショーから再開するときは、見本の本文を読みません。": "內建範例演出現在先載入清單，開啟時再載入內容，讓啟動更輕快。從已儲存的演出繼續時，不會載入範例內容。",
