  "照明・進行表・台本の言葉を、同じものは同じ名前で読めるように揃えました。": "統一了照明、流程表與台本的用語，相同內容使用相同名稱。",
  "書き出すファイル名を揃えました。中身は変わらず、旧い名前のファイルも読み込めます。": "統一了匯出檔名。內容不變，仍可讀取使用舊名稱的檔案。",
  "版を上げた最初の起動だけ、主な変更点を1行で表示するようにしました。": "更新後首次啟動時，會以一行文字顯示主要變更。",
  "キーボードのTabで、画面の流れに沿って操作へ移れるよう順路を改善しました。": "改善了鍵盤Tab順序，讓焦點依畫面流程移動。"
